; Exact one-shot MCP form, retained as data rather than a second runner.
(def refresh-form "(def turn-reds-b28-refresh\n (future\n  (let [started (System/nanoTime)\n        result\n        (try\n         (#'seon.test/with-test-loader\n          (fn []\n           (let [connection (seon.operator/connection \"default\")\n                 projection (seon.db/carried-projection (seon.db/db connection))]\n            (seon.schema/call-with-projection\n             projection\n             (fn []\n              (let [manifest (seon.fn/build-manifest {:seon.fn/roots seon.fn/source-roots})]\n               (when (:seon.error/kind manifest)\n                (throw (ex-info \"Fixture manifest refresh refused.\" manifest)))\n               (let [base (with-redefs-fn\n                           {#'seon.test-support/source-manifest (delay manifest)}\n                           #(#'seon.test-support/create-base nil))]\n                (alter-var-root #'seon.test-support/source-manifest (constantly (delay manifest)))\n                (alter-var-root #'seon.test-support/database-base (constantly (delay base)))\n                (.addShutdownHook (Runtime/getRuntime)\n                  (Thread. ^Runnable #(#'seon.test-support/close-base! base)\n                           \"turn-test-reds-refreshed-base-cleanup\"))\n                {:turn-test-reds/refreshed? true\n                 :turn-test-reds/contract\n                 (seon.db/pull\n                  (seon.db/db (:seon.test-support/connection base))\n                  [:seon.fn/spec] [:seon.fn/sym \"seon.test/stale\"])})))))))\n         (catch Throwable failure\n          {:turn-test-reds/refreshed? false\n           :turn-test-reds/failure (Throwable->map failure)}))\n        result (assoc result :turn-test-reds/wall-ms\n                      (/ (double (- (System/nanoTime) started)) 1000000.0))]\n   (spit \"tmp/turn-reds-b28-refresh.edn\" (pr-str result))\n   result)))")
